import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import Lottie from 'lottie-react';
import './Home.css';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

/**
 * VideoBackground Component
 * Displays an HTML5 video as a background element with fallback
 */
function VideoBackground({ src, className = '' }) {
  const videoRef = useRef(null);

  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.play().catch(() => {});
    }
  }, [src]);

  return (
    <div className={`absolute inset-0 overflow-hidden ${className}`}>
      <video
        ref={videoRef}
        autoPlay
        muted
        loop
        playsInline
        className="w-full h-full object-cover opacity-20"
        style={{ filter: 'blur(3px)' }}
      >
        <source src={src} type="video/mp4" />
      </video>
    </div>
  );
}

/**
 * Home Page - Main landing page
 * Features video background, category cards, product showcases,
 * Lottie animations, and business information sections.
 */
function Home({ addToCart }) {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState({});
  const [loading, setLoading] = useState(true);
  const [addedMsg, setAddedMsg] = useState('');
  const [activeVideoSection, setActiveVideoSection] = useState(0);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [prodRes, catRes] = await Promise.all([
        axios.get(`${API_URL}/api/products/`),
        axios.get(`${API_URL}/api/products/categories`)
      ]);
      setProducts(prodRes.data.products);
      setCategories(catRes.data.categories);
    } catch (err) {
      console.error('Error fetching data:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddToCart = (product) => {
    addToCart(product);
    setAddedMsg(product.name);
    setTimeout(() => setAddedMsg(''), 2000);
  };

  const getProductsByCategory = (category) => {
    return products.filter(p => p.category === category).slice(0, 4);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gradient-to-br from-red-50 to-orange-50">
        <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-gray-600 text-lg font-medium animate-pulse">Loading our delicious menu...</p>
      </div>
    );
  }

  return (
    <div className="home overflow-hidden">
      {/* Hero Section with Video Background */}
      <section className="relative min-h-screen flex items-center justify-center bg-gradient-to-br from-red-900 via-red-700 to-red-600 overflow-hidden">
        <VideoBackground src="https://cdn.coverr.co/videos/coverr-cooking-snacks-in-kitchen-5690/1080p.mp4" />
        
        {/* Animated floating particles */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          {[...Array(6)].map((_, i) => (
            <div
              key={i}
              className="absolute text-2xl opacity-10 animate-float"
              style={{
                left: `${10 + i * 18}%`,
                top: `${20 + (i % 3) * 30}%`,
                animationDelay: `${i * 0.5}s`,
                fontSize: `${2 + i * 0.5}rem`
              }}
            >
              {['🥨', '🍬', '🍮', '🥟', '🍪', '🧁'][i]}
            </div>
          ))}
        </div>

        <div className="relative z-10 text-center text-white px-6 max-w-5xl mx-auto">
          <div className="inline-block px-6 py-2 bg-white/10 backdrop-blur rounded-full text-sm font-medium mb-6 border border-white/20 animate-pulse">
            🏆 Traditional Taste Since Years
          </div>
          
          <h1 className="text-5xl md:text-7xl font-bold mb-4 font-serif leading-tight">
            Riddhi Siddhi
            <br />
            <span className="text-yellow-400">Modak Farsan</span>
          </h1>
          
          <p className="text-2xl md:text-3xl text-yellow-300 font-semibold mb-4">
            ✨ Shuddh Swad, Hamari Pehchaan ✨
          </p>
          
          <p className="text-lg md:text-xl text-white/80 max-w-2xl mx-auto mb-8 leading-relaxed">
            Authentic Maharashtrian namkeen, farsan & sweets made with love,
            tradition, and the finest ingredients
          </p>

          <div className="flex flex-wrap gap-4 justify-center mb-12">
            <Link to="/category/dry" className="group relative px-8 py-4 bg-yellow-400 text-red-900 rounded-full font-bold text-lg hover:bg-yellow-300 transition-all duration-300 transform hover:scale-105 hover:shadow-2xl">
              🥨 Explore Dry Items
              <span className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full animate-ping"></span>
            </Link>
            <Link to="/category/wet" className="px-8 py-4 bg-white/10 backdrop-blur text-white rounded-full font-bold text-lg border-2 border-white/30 hover:bg-white/20 transition-all duration-300 transform hover:scale-105">
              🍮 Fresh Sweets
            </Link>
          </div>

          <div className="flex justify-center gap-8 md:gap-16">
            {[
              { number: '50+', label: 'Products' },
              { number: '3km', label: 'Delivery Radius' },
              { number: '🚚', label: 'Free Delivery' }
            ].map((stat, i) => (
              <div key={i} className="text-center">
                <div className="text-3xl md:text-4xl font-bold text-yellow-400">{stat.number}</div>
                <div className="text-sm text-white/70 mt-1">{stat.label}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Scroll indicator */}
        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 animate-bounce">
          <div className="w-6 h-10 border-2 border-white/30 rounded-full flex justify-center">
            <div className="w-1.5 h-3 bg-white/50 rounded-full mt-2 animate-pulse"></div>
          </div>
        </div>
      </section>

      {/* Festival Banner with Animation */}
      <section className="relative overflow-hidden bg-gradient-to-r from-orange-500 via-red-500 to-pink-500 py-4">
        <div className="absolute inset-0 bg-[url('data:image/svg+xml,...')] opacity-10"></div>
        <div className="container mx-auto px-4 flex items-center justify-center gap-4 text-white">
          <span className="text-3xl animate-bounce">🎉</span>
          <div className="text-center">
            <p className="font-bold text-lg">Festival Season Alert!</p>
            <p className="text-sm opacity-90">Place orders <strong>20 days in advance</strong> for guaranteed freshness</p>
          </div>
          <span className="px-4 py-1 bg-white/20 rounded-full text-sm font-semibold">Advance Booking</span>
        </div>
      </section>

      {/* Categories Section with Hover Effects */}
      <section className="py-20 bg-gradient-to-b from-white to-orange-50">
        <div className="container mx-auto px-4">
          <h2 className="text-4xl md:text-5xl font-serif font-bold text-center text-red-800 mb-4">Our Categories</h2>
          <p className="text-center text-gray-500 text-lg mb-12">Explore our wide range of traditional delicacies</p>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 max-w-5xl mx-auto">
            {Object.entries(categories).map(([key, cat], index) => (
              <Link
                to={`/category/${key}`}
                key={key}
                className="group relative bg-white rounded-3xl p-8 text-center shadow-lg hover:shadow-2xl transition-all duration-500 transform hover:-translate-y-3 overflow-hidden"
              >
                <div className="absolute inset-0 bg-gradient-to-br from-red-50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
                <div className="relative z-10">
                  <div className="w-24 h-24 mx-auto mb-6 bg-gradient-to-br from-red-100 to-red-200 rounded-full flex items-center justify-center group-hover:scale-110 transition-transform duration-500 group-hover:shadow-xl">
                    <span className="text-4xl group-hover:animate-bounce">{cat.icon}</span>
                  </div>
                  <h3 className="text-xl font-bold text-gray-800 mb-3 group-hover:text-red-700 transition-colors">{cat.name}</h3>
                  <p className="text-gray-500 text-sm mb-4 line-clamp-2">{cat.description}</p>
                  <span className="inline-block px-4 py-1.5 bg-red-100 text-red-700 rounded-full text-sm font-semibold group-hover:bg-red-700 group-hover:text-white transition-all duration-300">
                    {cat.count} items →
                  </span>
                </div>
              </Link>
            ))}
          </div>
        </div>
      </section>

      {/* Featured Products - Dry Items with Video Card */}
      <section className="py-16 bg-white">
        <div className="container mx-auto px-4">
          <div className="flex items-center gap-4 mb-4">
            <span className="text-4xl">🥨</span>
            <h2 className="text-3xl md:text-4xl font-serif font-bold text-red-800">Dry Items (Namkeen & Farsan)</h2>
          </div>
          <p className="text-gray-500 text-lg mb-10">Crispy, crunchy and full of flavor - perfect tea-time snacks</p>
          
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {/* Video Card */}
            <div className="relative rounded-2xl overflow-hidden min-h-[320px] shadow-lg group">
              <video
                autoPlay
                muted
                loop
                playsInline
                className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
              >
                <source src="https://cdn.coverr.co/videos/coverr-cooking-snacks-in-kitchen-5690/1080p.mp4" type="video/mp4" />
              </video>
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/30 to-transparent"></div>
              <div className="absolute bottom-0 left-0 right-0 p-6">
                <span className="text-3xl mb-2 block">👨‍🍳</span>
                <h4 className="text-white font-bold text-lg">Freshly Made</h4>
                <p className="text-white/70 text-sm">Prepared fresh daily with traditional recipes</p>
              </div>
            </div>

            {getProductsByCategory('dry').map(product => (
              <div key={product._id} className="group bg-white rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl transition-all duration-500 transform hover:-translate-y-2">
                <div className="h-44 bg-gradient-to-br from-orange-50 to-amber-50 flex items-center justify-center">
                  <span className="text-6xl opacity-60 group-hover:scale-125 transition-transform duration-500">🥨</span>
                </div>
                <div className="p-5">
                  <h3 className="font-bold text-gray-800 mb-1 group-hover:text-red-700 transition-colors">{product.name}</h3>
                  <p className="text-sm text-gray-500 mb-3 line-clamp-2">{product.description}</p>
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-xl font-bold text-red-700">₹{product.price}/{product.unit}</span>
                    <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-xs font-semibold">In Stock</span>
                  </div>
                  <button
                    className="w-full py-2.5 bg-gray-100 hover:bg-red-700 hover:text-white rounded-xl font-semibold text-sm transition-all duration-300"
                    onClick={() => handleAddToCart(product)}
                  >
                    🛒 Add to Cart
                  </button>
                </div>
              </div>
            ))}
          </div>

          <div className="text-center mt-10">
            <Link to="/category/dry" className="inline-flex items-center gap-2 px-8 py-3 border-2 border-red-700 text-red-700 rounded-full font-semibold hover:bg-red-700 hover:text-white transition-all duration-300">
              View All Dry Items <span className="text-lg">→</span>
            </Link>
          </div>
        </div>
      </section>

      {/* Lottie Animation Break Section */}
      <section className="py-12 bg-gradient-to-r from-red-50 to-orange-50">
        <div className="container mx-auto px-4">
          <div className="flex flex-col md:flex-row items-center justify-center gap-8">
            <div className="w-32 h-32">
              <Lottie
                animationData="https://assets10.lottiefiles.com/packages/lf20_w98qte06.json"
                loop={true}
                autoplay={true}
                style={{ width: '100%', height: '100%' }}
              />
            </div>
            <div className="text-center md:text-left">
              <h3 className="text-2xl font-bold text-red-800">Free Delivery on Orders Above ₹300</h3>
              <p className="text-gray-600">Freshly prepared snacks delivered to your doorstep</p>
            </div>
          </div>
        </div>
      </section>

      {/* Featured Products - Sweet Items */}
      <section className="py-16 bg-gradient-to-b from-amber-50 to-orange-50">
        <div className="container mx-auto px-4">
          <div className="flex items-center gap-4 mb-4">
            <span className="text-4xl">🍬</span>
          </div>
        </div>
      </section>

      {/* Toast notification */}
      {addedMsg && (
        <div className="toast-notification">
          <span>✅</span> {addedMsg} added to cart!
        </div>
      )}
    </div>
  );
}

export default Home;
